            if (menu.getComponentCount() > 0) {
                menu.addSeparator();
            }
            JMenuItem transfer = new JMenuItem("Transfer Conversation");
            transfer.setToolTipText(buttonTip(
                    "Transfer Conversation copies this canvas into the Roux session after OK."
                            + "<br>The Roux turns become these prompts and replies."
                            + " Cancel leaves both sides as they are."));
