    /**
     * @return true when any per-user mood file is already on disk
     */
    private static boolean anyUserMoodFile() {
        File[] files = thinkHome().listFiles();
        if (files == null) {
            return false;
        }
        for (int i = 0; i < files.length; i++) {
            String name = files[i].getName();
            if (name.startsWith("aetheris-mood-") && name.endsWith(".yaml")) {
                return true;
            }
        }
        return false;
    }

    /**
     * The glass fields, copied so a later edit does not change the bank.
     *
     * @return the showing record
     */
    private MoodKeep liveMood() {
        MoodKeep keep = new MoodKeep();
        keep.line = moodLine == null ? "" : moodLine;
        keep.on = moodOn;
        keep.pending = moodPending;
        keep.width = moodDialogWidth;
        keep.height = moodDialogHeight;
        keep.blocked = moodStoreBlocked;
        keep.pins.putAll(moodPins);
        return keep;
    }

    /**
     * Paint one user's record on the glass.
     *
     * @param keep that record
     */
    private void applyMood(MoodKeep keep) {
        moodLine = keep.line == null ? "" : keep.line;
        moodPending = keep.pending;
        moodDialogWidth = keep.width;
        moodDialogHeight = keep.height;
        moodStoreBlocked = keep.blocked;
        moodPins.clear();
        moodPins.putAll(keep.pins);
        moodOn = keep.on && moodHasLine();
        syncMoodSwitch();
    }

    /**
     * Read version 1. A missing file is empty. Any other version is blocked and unread.
     *
     * @param file mood yaml
     * @return the record
     */
    private static MoodKeep readMoodFile(File file) {
        MoodKeep keep = MoodKeep.fresh();
        if (file == null || !file.isFile()) {
            return keep;
        }
        InputStreamReader reader = null;
        try {
            reader = new InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8);
            Object loaded = new Yaml().load(reader);
            if (!(loaded instanceof Map)) {
                keep.blocked = true;
                return keep;
            }
            Map<?, ?> root = (Map<?, ?>) loaded;
            if (!yamlVersionOne(root.get("version"))) {
                keep.blocked = true;
                return keep;
            }
            keep.line = yamlText(root.get("line"));
            keep.on = yamlFlag(root.get("on")) && keep.line != null && keep.line.trim().length() > 0;
            Object width = root.get("width");
            Object height = root.get("height");
            if (width instanceof Number && height instanceof Number) {
                keep.width = ((Number) width).intValue();
                keep.height = ((Number) height).intValue();
            }
            keep.pending = yamlFlag(root.get("pending"));
            Object pins = root.get("pins");
            if (pins instanceof Map) {
                Map<?, ?> map = (Map<?, ?>) pins;
                java.util.Iterator<? extends Map.Entry<?, ?>> it = map.entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<?, ?> entry = it.next();
                    if (entry.getKey() != null && entry.getValue() != null) {
                        keep.pins.put(String.valueOf(entry.getKey()), String.valueOf(entry.getValue()));
                    }
                }
            }
        } catch (Exception ex) {
            keep.blocked = true;
            keep.line = "";
            keep.on = false;
            keep.pending = false;
            keep.pins.clear();
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException ignored) {
                    // the record keeps what it already read
                }
            }
        }
        return keep;
    }

    /**
     * Seat {@code username}. Stash the user who was showing. Claim the shared file
     * only for the first user, and only when no per-user file exists yet.
     *
     * @param username canvas user
     */
    private void adoptMoodUser(String username) {
        // @aa-sdd PK-4328 docs/specs/java/org/aetheris/swing/swing.spec.md
        String want = sanitizeUser(username);
        if (want == null || want.length() == 0 || want.equals(moodOwner)) {
            return;
        }
        if (moodOwner != null && moodOwner.length() > 0) {
            moodBank.put(moodOwner, liveMood());
            saveMoodStore();
        }
        MoodKeep parked = moodBank.get(want);
        if (parked != null) {
            moodOwner = want;
            applyMood(parked);
            noteMoodRelay();
            return;
        }
        File own = moodUserFile(want);
        if (own.isFile()) {
            moodOwner = want;
            applyMood(readMoodFile(own));
            moodBank.put(want, liveMood());
            noteMoodRelay();
            return;
        }
        boolean claim = (moodOwner == null || moodOwner.length() == 0) && !anyUserMoodFile();
        if (claim) {
            File legacy = new File(thinkHome(), "aetheris-mood.yaml");
            if (legacy.isFile()) {
                MoodKeep loaded = readMoodFile(legacy);
                if (!loaded.blocked) {
                    moodOwner = want;
                    applyMood(loaded);
                    moodBank.put(want, liveMood());
                    saveMoodStore();
                    noteMoodRelay();
                    return;
                }
            }
        }
        moodOwner = want;
        applyMood(MoodKeep.fresh());
        moodBank.put(want, liveMood());
        noteMoodRelay();
    }

    /**
     * The record for a pane's user. A miss does not claim the shared file.
     *
     * @param key sanitized user
     * @return that record
     */
    private MoodKeep moodFor(String key) {
        if (key == null || key.length() == 0) {
            return MoodKeep.fresh();
        }
        if (key.equals(moodOwner)) {
            return liveMood();
        }
        MoodKeep have = moodBank.get(key);
        if (have != null) {
            return have;
        }
        File own = moodUserFile(key);
        if (!own.isFile()) {
            return MoodKeep.fresh();
        }
        MoodKeep loaded = readMoodFile(own);
        moodBank.put(key, loaded);
        return loaded;
    }

    /**
     * @return true when the kept pair is inside the dialog range
     */
    private boolean moodDialogSizeKept() {
        return moodDialogWidth >= 480 && moodDialogWidth <= 4000
                && moodDialogHeight >= 320 && moodDialogHeight <= 4000;
    }

    /**
     * Write the showing user's string, switch, and a kept dialog size.
     * A blocked file is not overwritten. The shared file is not rewritten.
     */
    private void saveMoodStore() {
        if (moodStoreBlocked || moodOwner == null || moodOwner.length() == 0) {
            return;
        }
        File dir = thinkHome();
        if (!dir.isDirectory()) {
            dir.mkdirs();
        }
        LinkedHashMap<String, Object> root = new LinkedHashMap<String, Object>();
        root.put("version", Integer.valueOf(1));
        root.put("line", moodLine == null ? "" : moodLine);
        root.put("on", Boolean.valueOf(moodOn && moodHasLine()));
        root.put("pending", Boolean.valueOf(moodPending));
        if (!moodPins.isEmpty()) {
            root.put("pins", new LinkedHashMap<String, String>(moodPins));
        }
        if (moodDialogSizeKept()) {
            root.put("width", Integer.valueOf(moodDialogWidth));
            root.put("height", Integer.valueOf(moodDialogHeight));
        }
        DumperOptions options = new DumperOptions();
        options.setDefaultFlowStyle(DumperOptions.FlowStyle.BLOCK);
        options.setPrettyFlow(true);
        OutputStreamWriter writer = null;
        try {
            writer = new OutputStreamWriter(
                    new FileOutputStream(moodUserFile(moodOwner)),
                    StandardCharsets.UTF_8);
            new Yaml(options).dump(root, writer);
        } catch (Exception ex) {
            return;
        } finally {
            if (writer != null) {
                try {
                    writer.close();
                } catch (Exception ignored) {
                    // a missed close still left the bytes already written
                }
            }
        }
    }

