    /**
     * Load version 1 of {@code ~/.casserole/aetheris-ssh-mood.yaml}.
     * Any other version is left unread. A missing file starts empty.
     */
    private void loadSshMoodStore() {
        File file = new File(thinkHome(), "aetheris-ssh-mood.yaml");
        if (!file.isFile()) {
            return;
        }
        InputStreamReader reader = null;
        try {
            reader = new InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8);
            Object loaded = new Yaml().load(reader);
            if (!(loaded instanceof Map)) {
                sshMoodBlocked = true;
                return;
            }
            Map<?, ?> root = (Map<?, ?>) loaded;
            if (!yamlVersionOne(root.get("version"))) {
                sshMoodBlocked = true;
                return;
            }
            Object users = root.get("users");
            if (!(users instanceof Map)) {
                return;
            }
            Map<?, ?> rows = (Map<?, ?>) users;
            java.util.Iterator<?> keys = rows.keySet().iterator();
            while (keys.hasNext()) {
                Object key = keys.next();
                if (key == null) {
                    continue;
                }
                String name = sanitizeUser(String.valueOf(key));
                if (name.length() == 0 || "anon".equals(name)) {
                    continue;
                }
                sshMoodUsers.put(name, Boolean.valueOf(yamlFlag(rows.get(key))));
            }
        } catch (Exception ex) {
            sshMoodBlocked = true;
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException ignored) {
                    // the map keeps what it already read
                }
            }
        }
    }

