                    cell.groupId = group;
                    cell.columnPosition = column;
                    if (hasDonor) {
                        cell.executionTarget = priorTarget;
                    }
                    vault.saveCell(cell);
                    canvas.cells.add(cell);
                    canvas.cellOrder.add(cell.id);
                    snapGroup(canvas, group);
                    vault.saveOrder(canvas.id, canvas.cellOrder);
