    /**
     * @param cell   turn
     * @param field  group-bar field
     * @param target stored execution target
     */
    private void paintCellTarget(CellRecord cell, JTextField field, String target) {
        if (cell == null) {
            return;
        }
        cell.executionTarget = target == null ? "" : target;
        if (field != null) {
            field.setText(cell.executionTarget);
        }
        CellCard card = findCard(cell.id);
        if (card != null) {
            card.paintModelLabel();
        }
    }

    /**
     * Empty model. Effort {@code high}. This row is not {@link GrokSettingsDocument#factory()}.
     *
     * @param model model id. Empty stays empty.
     * @return a new entry
     */
    private static GrokSettingsDocument.Entry blankGrok(String model) {
        GrokSettingsDocument.Entry entry = new GrokSettingsDocument.Entry();
        entry.api = "chat";
        entry.model = model == null ? "" : model;
        entry.reasoningEffort = "high";
        entry.sendReasoningEffort = GrokSettingsDocument.sendsEffort(entry.model);
        entry.stream = false;
        entry.burnerCloud = false;
        entry.temperature = 1.0d;
        entry.maxCompletionTokens = 128000;
        return entry;
    }

    /**
     * @param cellId vault cell id
     * @return the session holder. A missing key is created off, with no level.
     */
    private CellThink thinkOf(String cellId) {
        CellThink held = ollamaThink.get(cellId);
        if (held == null) {
            held = new CellThink();
            ollamaThink.put(cellId, held);
        }
        return held;
    }

    /**
     * Keep the Ollama id when the stored target is still Ollama.
     *
     * @param cellId vault cell id
     * @param target stored execution target
     */
    private void rememberOllamaId(String cellId, String target) {
        if (cellId == null || !"ollama".equals(AetherisStage2.providerId(target))) {
            return;
        }
        thinkOf(cellId).ollamaId = AetherisStage2.modelAfterSlash(target);
        saveThinkStore();
    }

    /**
     * Copy the source cell's Grok thinking flag onto the destination holder.
     *
     * @param destId   cell that received the document
     * @param sourceId cell the document was copied from
     */
    private void copyGrokOn(String destId, String sourceId) {
        if (destId == null || sourceId == null) {
            return;
        }
        CellThink source = ollamaThink.get(sourceId);
        if (source == null) {
            return;
        }
        thinkOf(destId).grokOn = source.grokOn;
        saveThinkStore();
    }

    /**
     * Ollama with no id reads {@code ollama}. Ollama with an id reads that id.
     * Grok reads the id after {@code grok/}. Grok with no id reads {@code grok}.
     * Pool reads {@code pool}. Any other provider reads blank.
     *
     * @param target stored execution target
     * @return the label line
     */
    private static String shortModelName(String target) {
        String provider = AetherisStage2.providerId(target);
        if ("ollama".equals(provider)) {
            String id = AetherisStage2.modelAfterSlash(target);
            if (id.length() == 0) {
                return "ollama";
            }
            return id;
        }
        if ("grok".equals(provider)) {
            String id = AetherisStage2.modelAfterSlash(target);
            if (id.length() == 0) {
                return "grok";
            }
            return id;
        }
        if ("pool".equals(provider)) {
            return "pool";
        }
        return "";
    }

    /**
     * Drop the modal fields. The cell stays as last written.
     */
    private void clearModelDialog() {
        grokDialogOpen = false;
        dialogAdjusting = false;
        dialogCellId = "";
        dialogShowId = "";
        dialogCell = null;
        dialogCardField = null;
        dialogConsole = false;
        dialogConsoleThink = "";
        dialogFamily = null;
        dialogOllamaId = null;
        dialogOllamaEffort = null;
        dialogOllamaThink = null;
        dialogOllamaEffortRow = null;
        dialogGrokModel = null;
        dialogGrokEffort = null;
        dialogGrokSendEffort = null;
        dialogGrokStream = null;
        dialogGrokThink = null;
        dialogPoolThink = null;
        dialogGrokBurner = null;
        dialogGrokTemperature = null;
        dialogGrokMaxTokens = null;
        modelDialog = null;
    }

    /**
     * Write the Ollama target from the id this cell already holds.
     */
    private void applyOllamaFamily() {
        if (dialogCell == null) {
            return;
        }
        CellThink held = thinkOf(dialogCell.id);
        String id = held.ollamaId == null ? "" : held.ollamaId.trim();
        if (dialogOllamaId != null) {
            dialogAdjusting = true;
            setDialogOllamaModelId(id);
            dialogAdjusting = false;
        }
        String target = id.length() == 0 ? "" : "ollama/" + id;
        paintCellTarget(dialogCell, dialogCardField, target);
        persistQuiet(dialogCell);
    }

    /**
     * Selecting Pool stores the bare word {@code pool}. No Grok settings row. {@code poolOn} stays as it is.
     */
    private void applyPoolFamily() {
        if (dialogCell == null) {
            return;
        }
        if (dialogOllamaId != null && "ollama".equals(AetherisStage2.providerId(dialogCell.executionTarget))) {
            String id = dialogOllamaModelId();
            thinkOf(dialogCell.id).ollamaId = id;
        }
        paintCellTarget(dialogCell, dialogCardField, "pool");
        if (dialogPoolThink != null) {
            CellThink held = ollamaThink.get(dialogCell.id);
            dialogAdjusting = true;
            dialogPoolThink.setSelected(held != null && held.poolOn);
            dialogAdjusting = false;
        }
        persistQuiet(dialogCell);
    }

    /**
     * Selecting Grok copies the nearest document, else standing, else an empty model at {@code high}.
     * The target is {@code grok/} before that copy, so an Ollama id is not stored as the Grok model.
     */
    private void applyGrokFamily() {
        if (dialogCell == null) {
            return;
        }
        if (dialogOllamaId != null && "ollama".equals(AetherisStage2.providerId(dialogCell.executionTarget))) {
            String id = dialogOllamaModelId();
            thinkOf(dialogCell.id).ollamaId = id;
        }
        String typed = "";
        if ("grok".equals(AetherisStage2.providerId(dialogCell.executionTarget))) {
            typed = AetherisStage2.modelAfterSlash(dialogCell.executionTarget);
        }
        GrokSettingsDocument.Entry existing = grokDoc.entry(dialogCell.id);
        if (existing != null) {
            String model = existing.model == null ? "" : existing.model;
            if (typed.length() > 0) {
                model = typed;
                existing.model = typed;
                existing.reasoningEffort = GrokSettingsDocument.normalizeEffort(typed, existing.reasoningEffort);
                grokDoc.write(dialogCell.id, existing, false);
            }
            String target = model.length() == 0 ? "grok/" : "grok/" + model;
            paintCellTarget(dialogCell, dialogCardField, target);
            persistQuiet(dialogCell);
            return;
        }
        paintCellTarget(dialogCell, dialogCardField, "grok/");
        GrokSettingsDocument.Entry source = nearestGrok(dialogCell);
        String sourceId = nearestGrokId(dialogCell);
        if (source == null) {
            source = grokDoc.standing();
            sourceId = null;
        }
        if (typed.length() > 0) {
            GrokSettingsDocument.Entry entry = source == null ? blankGrok(typed) : source.copy();
            entry.model = typed;
            entry.reasoningEffort = GrokSettingsDocument.normalizeEffort(typed, entry.reasoningEffort);
            grokDoc.write(dialogCell.id, entry, false);
            if (sourceId != null) {
                copyGrokOn(dialogCell.id, sourceId);
            }
            paintCellTarget(dialogCell, dialogCardField, "grok/" + typed);
            persistQuiet(dialogCell);
            return;
        }
        if (source != null && source.model != null && source.model.length() > 0) {
            GrokSettingsDocument.Entry entry = source.copy();
            entry.reasoningEffort = GrokSettingsDocument.normalizeEffort(entry.model, entry.reasoningEffort);
            grokDoc.write(dialogCell.id, entry, false);
            if (sourceId != null) {
                copyGrokOn(dialogCell.id, sourceId);
            }
            paintCellTarget(dialogCell, dialogCardField, "grok/" + entry.model);
            persistQuiet(dialogCell);
            return;
        }
        grokDoc.write(dialogCell.id, blankGrok(""), false);
        paintCellTarget(dialogCell, dialogCardField, "grok/");
        persistQuiet(dialogCell);
    }

    /**
     * The effort pull-down stays visible. It is enabled only while Send effort is on.
     */
    private void applySendEffortChrome() {
        if (dialogGrokEffort == null) {
            return;
        }
        boolean on = dialogGrokSendEffort == null || dialogGrokSendEffort.isSelected();
        dialogGrokEffort.setEnabled(on);
    }

    /**
     * The host refused {@code reasoning_effort} for this cell. Store the switch off.
     *
     * @param cellId vault cell id
     */
    private void markEffortOff(String cellId) {
        if (cellId == null || cellId.length() == 0) {
            return;
        }
        GrokSettingsDocument.Entry entry = grokDoc.entry(cellId);
        if (entry == null) {
            return;
        }
        entry.sendReasoningEffort = false;
        grokDoc.write(cellId, entry, false);
        if (grokDialogOpen && cellId.equals(dialogCellId) && dialogGrokSendEffort != null) {
            dialogAdjusting = true;
            dialogGrokSendEffort.setSelected(false);
            applySendEffortChrome();
            dialogAdjusting = false;
        }
    }

    /**
     * Fill the Grok pane from the cell document. An empty model stays unselected.
     * Listeners stay quiet while the rows are filled.
     * The catalog ask waits until the modal is open, then runs when the family is Grok.
     * A family change to Grok asks again. The static rows stay until that reply carries model lines.
     */
    private void loadGrokControls() {
        if (dialogGrokModel == null || dialogGrokEffort == null) {
            return;
        }
        dialogAdjusting = true;
        GrokSettingsDocument.Entry entry;
        if (dialogConsole) {
            entry = consoleGrok;
        } else {
            entry = dialogCell == null ? null : grokDoc.entry(dialogCell.id);
        }
        String modelId = entry == null || entry.model == null ? "" : entry.model;
        fillModels(dialogGrokModel, modelId);
        String effortModel = dialogGrokModel.getSelectedItem() == null
                ? modelId : String.valueOf(dialogGrokModel.getSelectedItem());
        String effort = entry == null ? "high" : entry.reasoningEffort;
        fillEffort(dialogGrokEffort, effortModel, effort);
        if (dialogGrokSendEffort != null) {
            boolean send = entry == null
                    ? GrokSettingsDocument.sendsEffort(effortModel) : entry.sendReasoningEffort;
            dialogGrokSendEffort.setSelected(send);
        }
        applySendEffortChrome();
        if (dialogGrokStream != null) {
            dialogGrokStream.setSelectedItem(entry != null && entry.stream ? "true" : "false");
        }
        if (dialogGrokBurner != null) {
            dialogGrokBurner.setSelected(entry != null && entry.burnerCloud);
        }
        if (dialogGrokTemperature != null) {
            dialogGrokTemperature.setText(numberText(entry == null ? 1.0d : entry.temperature));
        }
        if (dialogGrokMaxTokens != null) {
            int max = entry == null ? 128000 : entry.maxCompletionTokens;
            dialogGrokMaxTokens.setText(Integer.toString(max));
        }
        if (dialogGrokThink != null) {
            if (dialogConsole) {
                dialogGrokThink.setSelected("true".equals(consoleGrokThink));
            } else if (dialogCell != null) {
                CellThink held = ollamaThink.get(dialogCell.id);
                dialogGrokThink.setSelected(held != null && held.grokOn);
            }
        }
        dialogAdjusting = false;
        if (grokDialogOpen
                && dialogFamily != null
                && "Grok".equals(String.valueOf(dialogFamily.getSelectedItem()))) {
            askGrokModels(dialogCellId);
        }
    }

    /**
     * Write the Grok controls that are combos and checkboxes. Temperature and max tokens write on focus loss.
     * An empty model does not become the standing default.
     */
    private void writeGrokControls() {
        if (dialogAdjusting) {
            return;
        }
        if (dialogCell == null) {
            if (dialogConsole) {
                sendConsoleSet();
            }
            return;
        }
        GrokSettingsDocument.Entry entry = grokDoc.entry(dialogCell.id);
        if (entry == null) {
            entry = blankGrok("");
        }
        if (dialogGrokModel != null && dialogGrokModel.getSelectedItem() != null) {
            entry.model = String.valueOf(dialogGrokModel.getSelectedItem());
        }
        String effort = entry.reasoningEffort;
        if (dialogGrokEffort != null && dialogGrokEffort.getSelectedItem() != null) {
            effort = String.valueOf(dialogGrokEffort.getSelectedItem());
        }
        entry.reasoningEffort = GrokSettingsDocument.normalizeEffort(entry.model, effort);
        if (dialogGrokSendEffort != null) {
            entry.sendReasoningEffort = dialogGrokSendEffort.isSelected();
        }
        if (dialogGrokStream != null && dialogGrokStream.getSelectedItem() != null) {
            entry.stream = "true".equals(String.valueOf(dialogGrokStream.getSelectedItem()));
        }
        if (dialogGrokBurner != null) {
            entry.burnerCloud = dialogGrokBurner.isSelected();
        }
        grokDoc.write(dialogCell.id, entry, false);
        persistQuiet(dialogCell);
    }

    /**
     * A finite double writes. Anything else keeps the stored temperature and the status line says {@code settings}.
     */
    private void writeGrokTemperature() {
        if (dialogAdjusting || dialogGrokTemperature == null) {
            return;
        }
        if (dialogCell == null) {
            if (dialogConsole) {
                sendConsoleSet();
            }
            return;
        }
        String text = dialogGrokTemperature.getText() == null ? "" : dialogGrokTemperature.getText().trim();
        double temp;
        try {
            temp = Double.parseDouble(text);
        } catch (NumberFormatException ex) {
            host.aetherisStatus(statusLine("settings"));
            return;
        }
        if (Double.isInfinite(temp) || Double.isNaN(temp)) {
            host.aetherisStatus(statusLine("settings"));
            return;
        }
        GrokSettingsDocument.Entry entry = grokDoc.entry(dialogCell.id);
        if (entry == null) {
            entry = blankGrok("");
        }
        entry.temperature = temp;
        grokDoc.write(dialogCell.id, entry, false);
        persistQuiet(dialogCell);
    }

    /**
     * An int of 1 or more writes. Anything else keeps the stored cap and the status line says {@code settings}.
     */
    private void writeGrokMaxTokens() {
        if (dialogAdjusting || dialogGrokMaxTokens == null) {
            return;
        }
        if (dialogCell == null) {
            if (dialogConsole) {
                sendConsoleSet();
            }
            return;
        }
        String text = dialogGrokMaxTokens.getText() == null ? "" : dialogGrokMaxTokens.getText().trim();
        int max;
        try {
            max = Integer.parseInt(text);
        } catch (NumberFormatException ex) {
            host.aetherisStatus(statusLine("settings"));
            return;
        }
        if (max < 1) {
            host.aetherisStatus(statusLine("settings"));
            return;
        }
        GrokSettingsDocument.Entry entry = grokDoc.entry(dialogCell.id);
        if (entry == null) {
            entry = blankGrok("");
        }
        entry.maxCompletionTokens = max;
        grokDoc.write(dialogCell.id, entry, false);
        persistQuiet(dialogCell);
    }

    /**
     * Hide the Ollama effort rows until a show reply lists levels.
     */
    private void hideOllamaEffort() {
        dialogAdjusting = true;
        if (dialogOllamaEffort != null) {
            dialogOllamaEffort.removeAllItems();
            if (dialogOllamaEffort.getItemCount() == 0) {
                dialogOllamaEffort.setSelectedIndex(-1);
            }
        }
        if (dialogOllamaEffortRow != null) {
            dialogOllamaEffortRow.setVisible(false);
        }
        dialogAdjusting = false;
    }

    /**
     * The effort pull-down shows when Thinking is on and the reply listed a level.
     */
    private void refreshOllamaEffortRow() {
        if (dialogOllamaEffortRow == null || dialogOllamaEffort == null) {
            return;
        }
        boolean on = dialogOllamaThink != null && dialogOllamaThink.isSelected();
        dialogOllamaEffortRow.setVisible(on && dialogOllamaEffort.getItemCount() > 0);
    }

    /**
     * Apply {@code show_result:} while this modal is open on that cell and the id still matches.
     *
     * @param cellId cell on the frame
     * @param text   stripped body
     */
    private void applyShowResult(String cellId, String text) {
        if (!grokDialogOpen || cellId == null || !cellId.equals(dialogCellId)) {
            return;
        }
        if (dialogOllamaId == null || dialogOllamaEffort == null) {
            return;
        }
        String id = showResultModel(text);
        String current = dialogOllamaModelId();
        if (current.length() == 0 && id.length() > 0) {
            dialogAdjusting = true;
            setDialogOllamaModelId(id);
            dialogShowId = id;
            dialogAdjusting = false;
            current = id;
        } else if (!id.equals(current)) {
            return;
        }
        ArrayList<String> values = showResultValues(text);
        dialogAdjusting = true;
        dialogOllamaEffort.removeAllItems();
        for (int i = 0; i < values.size(); i++) {
            dialogOllamaEffort.addItem(values.get(i));
        }
        String level = "";
        if (dialogConsole) {
            String seed = dialogConsoleThink == null ? "" : dialogConsoleThink;
            if (seed.length() > 0 && !"true".equals(seed) && !"false".equals(seed)) {
                level = seed;
            }
        } else {
            CellThink held = ollamaThink.get(cellId);
            if (held != null && held.ollamaLevel != null) {
                level = held.ollamaLevel;
            }
        }
        boolean found = false;
        for (int i = 0; i < values.size(); i++) {
            if (values.get(i).equals(level)) {
                found = true;
            }
        }
        if (found) {
            dialogOllamaEffort.setSelectedItem(level);
        } else if (dialogOllamaEffort.getItemCount() > 0) {
            dialogOllamaEffort.setSelectedIndex(-1);
        }
        dialogAdjusting = false;
        refreshOllamaEffortRow();
        if (dialogOllamaEffortRow != null) {
            dialogOllamaEffortRow.revalidate();
        }
        if (modelDialog != null) {
            modelDialog.pack();
        }
    }

    /**
     * @return the model id typed or chosen in the Ollama pane. Empty when the pane is closed.
     */
    private String dialogOllamaModelId() {
        if (dialogOllamaId == null) {
            return "";
        }
        Component editor = dialogOllamaId.getEditor().getEditorComponent();
        if (editor instanceof JTextField) {
            String text = ((JTextField) editor).getText();
            return text == null ? "" : text.trim();
        }
        Object selected = dialogOllamaId.getSelectedItem();
        return selected == null ? "" : String.valueOf(selected).trim();
    }

    /**
     * Paint the Ollama model id into the combo. An unknown id is added so a typed tag survives a refill.
     *
     * @param id model id. Empty clears the selection.
     */
    private void setDialogOllamaModelId(String id) {
        if (dialogOllamaId == null) {
            return;
        }
        boolean prior = dialogAdjusting;
        dialogAdjusting = true;
        String text = id == null ? "" : id.trim();
        if (text.length() == 0) {
            dialogOllamaId.setSelectedIndex(-1);
            dialogOllamaId.getEditor().setItem("");
            dialogAdjusting = prior;
            return;
        }
        boolean known = false;
        for (int i = 0; i < dialogOllamaId.getItemCount(); i++) {
            if (text.equals(String.valueOf(dialogOllamaId.getItemAt(i)))) {
                known = true;
            }
        }
        if (!known) {
            dialogOllamaId.addItem(text);
        }
        dialogOllamaId.setSelectedItem(text);
        dialogOllamaId.getEditor().setItem(text);
        dialogAdjusting = prior;
    }

    /**
     * The Ollama pane writes the cell while that family is the selected item.
     * A missing combo keeps the old write. The console path does not call this.
     * // @aa-sdd PK-4190 docs/specs/java/org/aetheris/swing/swing.spec.md
     *
     * @return true when an ollama id may land on the cell
     */
    private boolean ollamaPaneOwnsCell() {
        if (dialogFamily == null) {
            return true;
        }
        Object chosen = dialogFamily.getSelectedItem();
        return chosen != null && "Ollama".equals(String.valueOf(chosen));
    }

    /**
     * Write the Ollama id onto the cell. {@code askShow} sends {@code show:} for that id.
     * An empty id hides effort and does not ask.
     * The cell path stays idle once the family item is Grok or Pool.
     *
     * @param askShow whether to ask the host about this id
     */
    private void commitOllamaModel(boolean askShow) {
        if (dialogConsole) {
            commitConsoleModel(askShow);
            return;
        }
        if (dialogAdjusting || dialogCell == null || dialogOllamaId == null) {
            return;
        }
        if (!ollamaPaneOwnsCell()) {
            return;
        }
        String id = dialogOllamaModelId();
        thinkOf(dialogCell.id).ollamaId = id;
        saveThinkStore();
        String target = id.length() == 0 ? "" : "ollama/" + id;
        paintCellTarget(dialogCell, dialogCardField, target);
        persistQuiet(dialogCell);
        if (!askShow) {
            return;
        }
        if (id.length() == 0) {
            hideOllamaEffort();
            dialogShowId = "";
            return;
        }
        if (!id.equals(dialogShowId)) {
            hideOllamaEffort();
            dialogShowId = id;
        }
        askOllamaShow(dialogCell.id, id);
    }

    /**
     * Write the console model. An empty id does not clear the shell name. An empty think clears it.
     *
     * @param askShow whether to ask the host about this id
     */
    private void commitConsoleModel(boolean askShow) {
        if (dialogAdjusting || !dialogConsole || dialogOllamaId == null) {
            return;
        }
        String id = dialogOllamaModelId();
        String think = consoleThinkValue();
        if (think.length() > 0 && !"true".equals(think) && !"false".equals(think)) {
            dialogConsoleThink = think;
        }
        sendConsoleSet();
        if (!askShow) {
            return;
        }
        if (id.length() == 0) {
            hideOllamaEffort();
            dialogShowId = "";
            return;
        }
        if (!id.equals(dialogShowId)) {
            hideOllamaEffort();
            dialogShowId = id;
        }
        askOllamaShow(CONSOLE_CELL, id);
    }

    /**
     * Checkbox off is empty. Checkbox on with no level is {@code true}. A chosen level is that level.
     *
     * @return the think string this console stores
     */
    private String consoleThinkValue() {
        if (dialogOllamaThink == null || !dialogOllamaThink.isSelected()) {
            return "";
        }
        if (dialogOllamaEffort != null && dialogOllamaEffort.getSelectedItem() != null) {
            String level = String.valueOf(dialogOllamaEffort.getSelectedItem()).trim();
            if (level.length() > 0) {
                return level;
            }
        }
        return "true";
    }

    /**
     * First Grok choice with an empty id copies the standing row in memory.
     * The file stays unwritten for the nil cell.
     */
    private void ensureConsoleGrok() {
        String model = consoleGrok == null || consoleGrok.model == null ? "" : consoleGrok.model.trim();
        if (consoleGrok != null && model.length() > 0) {
            return;
        }
        GrokSettingsDocument.Entry standing = grokDoc.standing();
        if (standing != null) {
            consoleGrok = standing.copy();
            return;
        }
        if (consoleGrok == null) {
            consoleGrok = blankGrok("");
        }
    }

    /**
     * @return {@code ollama}, {@code grok}, {@code pool}, or empty when the combo has no row
     */
    private String consoleFamilyWord() {
        if (dialogFamily == null || dialogFamily.getSelectedItem() == null) {
            return "";
        }
        String chosen = String.valueOf(dialogFamily.getSelectedItem());
        if ("Grok".equals(chosen)) {
            return "grok";
        }
        if ("Pool".equals(chosen)) {
            return "pool";
        }
        if ("Ollama".equals(chosen)) {
            return "ollama";
        }
        return "";
    }

    /**
     * One full {@code shell_model_set:} for this console. A bad temperature or max token value
     * sets the status line {@code settings} and does not send. Nil cell id. Off the EDT.
     */
    private void sendConsoleSet() {
        if (dialogAdjusting || !dialogConsole) {
            return;
        }
        String family = consoleFamilyWord();
        if (family.length() == 0) {
            return;
        }
        String tempText = dialogGrokTemperature == null || dialogGrokTemperature.getText() == null
                ? "" : dialogGrokTemperature.getText().trim();
        boolean tempPresent = false;
        double temp = 0d;
        if (tempText.length() > 0) {
            try {
                temp = Double.parseDouble(tempText);
            } catch (NumberFormatException ex) {
                host.aetherisStatus(statusLine("settings"));
                return;
            }
            if (Double.isInfinite(temp) || Double.isNaN(temp)) {
                host.aetherisStatus(statusLine("settings"));
                return;
            }
            tempPresent = true;
        }
        String maxText = dialogGrokMaxTokens == null || dialogGrokMaxTokens.getText() == null
                ? "" : dialogGrokMaxTokens.getText().trim();
        boolean maxPresent = false;
        int max = 0;
        if (maxText.length() > 0) {
            try {
                max = Integer.parseInt(maxText);
            } catch (NumberFormatException ex) {
                host.aetherisStatus(statusLine("settings"));
                return;
            }
            if (max < 1) {
                host.aetherisStatus(statusLine("settings"));
                return;
            }
            maxPresent = true;
        }
        String ollamaId = dialogOllamaModelId();
        String think = consoleThinkValue();
        if (think.length() > 0 && !"true".equals(think) && !"false".equals(think)) {
            dialogConsoleThink = think;
        }
        String grokModel = "";
        if (dialogGrokModel != null && dialogGrokModel.getSelectedItem() != null) {
            grokModel = String.valueOf(dialogGrokModel.getSelectedItem()).trim();
        }
        String effort = "";
        if (dialogGrokEffort != null && dialogGrokEffort.getSelectedItem() != null) {
            effort = String.valueOf(dialogGrokEffort.getSelectedItem()).trim();
        }
        effort = GrokSettingsDocument.normalizeEffort(grokModel, effort);
        boolean sendEffort = dialogGrokSendEffort == null || dialogGrokSendEffort.isSelected();
        boolean stream = dialogGrokStream != null && dialogGrokStream.getSelectedItem() != null
                && "true".equals(String.valueOf(dialogGrokStream.getSelectedItem()));
        boolean burner = dialogGrokBurner != null && dialogGrokBurner.isSelected();
        String grokThink = dialogGrokThink != null && dialogGrokThink.isSelected() ? "true" : "";
        String poolThink = dialogPoolThink != null && dialogPoolThink.isSelected() ? "true" : "";
        if (consoleGrok == null) {
            consoleGrok = blankGrok(grokModel);
        }
        consoleGrok.model = grokModel;
        consoleGrok.reasoningEffort = effort;
        consoleGrok.sendReasoningEffort = sendEffort;
        consoleGrok.stream = stream;
        consoleGrok.burnerCloud = burner;
        if (tempPresent) {
            consoleGrok.temperature = temp;
        }
        if (maxPresent) {
            consoleGrok.maxCompletionTokens = max;
        }
        consoleGrokThink = grokThink;
        consolePoolOn = "true".equals(poolThink);
        consoleProvider = family;
        consoleOllamaModel = ollamaId;
        consoleOllamaThink = think;
        final String body = "shell_model_set:\n"
                + "provider: " + cleanWire(family) + "\n"
                + "model: " + cleanWire(ollamaId) + "\n"
                + "ollama_model: " + cleanWire(ollamaId) + "\n"
                + "think: " + cleanWire(think) + "\n"
                + "grok_model: " + cleanWire(grokModel) + "\n"
                + "grok_think: " + cleanWire(grokThink) + "\n"
                + "effort: " + cleanWire(effort) + "\n"
                + "send_effort: " + (sendEffort ? "true" : "false") + "\n"
                + "stream: " + (stream ? "true" : "false") + "\n"
                + (tempPresent ? "temperature: " + numberText(temp) + "\n" : "")
                + (maxPresent ? "max_tokens: " + max + "\n" : "")
                + "burner: " + (burner ? "true" : "false") + "\n"
                + "pool_think: " + cleanWire(poolThink) + "\n";
        final SshTtyConnector connector = host.focusedAmwpConnector();
        if (connector == null || !connector.isAmwp()) {
            return;
        }
        /**
         * The run action sends the console model text on the frame channel.
         * The action encodes {@code body} as UTF-8.
         * The action calls {@link AmwpCodec#scopeAPayload} with {@code 0}, {@code 1}, null, and those bytes.
         * The action calls {@link SshTtyConnector#writeAmwp} with {@link AmwpConstants#CHANNEL_A} and {@link AmwpConstants#TYPE_DATA}.
         * If the write throws, the action ignores the exception.
         */
        Thread worker = new Thread(new Runnable() {
            // @aa-sdd PK-0658 docs/specs/java/org/casserole/llm/llm.spec.md
            @Override
            public void run() {
                try {
                    byte[] utf = body.getBytes(StandardCharsets.UTF_8);
                    byte[] payload = AmwpCodec.scopeAPayload(0, 1, null, utf);
                    connector.writeAmwp(AmwpConstants.CHANNEL_A, AmwpConstants.TYPE_DATA, payload);
                } catch (Exception ignored) {
                    // the modal keeps the last value it showed
                }
            }
        }, "aetheris-shell-model-set");
        worker.setDaemon(true);
        worker.start();
    }

    /**
     * @param raw field
     * @return the same text with CR and LF removed
     */
    private static String cleanWire(String raw) {
        if (raw == null || raw.length() == 0) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < raw.length(); i++) {
            char c = raw.charAt(i);
            if (c == '\r' || c == '\n') {
                continue;
            }
            sb.append(c);
        }
        return sb.toString();
    }

    /**
     * Open the console dialog from {@code shell_model_result:}. A real cell id is ignored.
     * An open dialog is left as it is. A close that already marked the dialog quiet stays closed.
     *
     * @param cellId frame cell
     * @param text   stripped body
     */
    private void applyShellModelResult(String cellId, String text) {
        if (cellId == null || !CONSOLE_CELL.equals(cellId) || grokDialogOpen || consoleDialogDismissed) {
            return;
        }
        String provider = shellLine(text, "provider:");
        if (provider.length() == 0) {
            provider = "ollama";
        }
        consoleProvider = provider;
        String ollama = shellLine(text, "ollama_model:");
        if (ollama.length() == 0) {
            ollama = shellLine(text, "model:");
        }
        consoleOllamaModel = ollama;
        String grokModel = shellLine(text, "grok_model:");
        GrokSettingsDocument.Entry entry = blankGrok(grokModel);
        String effort = shellLine(text, "effort:");
        if (effort.length() > 0) {
            entry.reasoningEffort = GrokSettingsDocument.normalizeEffort(grokModel, effort);
        }
        String send = shellLine(text, "send_effort:");
        if ("false".equals(send)) {
            entry.sendReasoningEffort = false;
        } else if ("true".equals(send)) {
            entry.sendReasoningEffort = true;
        }
        entry.stream = "true".equals(shellLine(text, "stream:"));
        entry.burnerCloud = "true".equals(shellLine(text, "burner:"));
        String temp = shellLine(text, "temperature:");
        if (temp.length() > 0) {
            try {
                double parsed = Double.parseDouble(temp);
                if (!Double.isInfinite(parsed) && !Double.isNaN(parsed)) {
                    entry.temperature = parsed;
                }
            } catch (NumberFormatException ignored) {
                // factory temperature stays
            }
        }
        String max = shellLine(text, "max_tokens:");
        if (max.length() > 0) {
            try {
                int parsed = Integer.parseInt(max);
                if (parsed >= 1) {
                    entry.maxCompletionTokens = parsed;
                }
            } catch (NumberFormatException ignored) {
                // factory cap stays
            }
        }
        consoleGrok = entry;
        consoleGrokThink = shellLine(text, "grok_think:");
        consolePoolOn = "true".equals(shellLine(text, "pool_think:"));
        consoleOllamaThink = shellLine(text, "think:");
        openConsoleDialog(ollama, consoleOllamaThink);
    }

    /**
     * @param text body
     * @param key  line prefix, including the colon
     * @return the value, or empty when the line is missing
     */
    private static String shellLine(String text, String key) {
        if (text == null || key == null) {
            return "";
        }
        int start = 0;
        while (start <= text.length()) {
            int nl = text.indexOf('\n', start);
            String line = nl < 0 ? text.substring(start) : text.substring(start, nl);
            if (line.endsWith("\r")) {
                line = line.substring(0, line.length() - 1);
            }
            if (line.startsWith(key)) {
                return line.substring(key.length()).trim();
            }
            if (nl < 0) {
                break;
            }
            start = nl + 1;
        }
        return "";
    }

    /**
     * Fill the Ollama model combo from {@code tags_result:} while this modal is open on that cell.
     *
     * @param cellId cell on the frame
     * @param text   stripped body
     */
    private void applyTagsResult(String cellId, String text) {
        if (!grokDialogOpen || !sameDialogCell(cellId, dialogCellId) || dialogOllamaId == null) {
            return;
        }
        String current = dialogOllamaModelId();
        ArrayList<String> names = ollamaHostRows(text, current);
        boolean reopen = dialogOllamaId.isPopupVisible();
        dialogAdjusting = true;
        dialogOllamaId.removeAllItems();
        for (int i = 0; i < names.size(); i++) {
            dialogOllamaId.addItem(names.get(i));
        }
        int rows = dialogOllamaId.getItemCount();
        dialogOllamaId.setMaximumRowCount(rows > 0 ? rows : 1);
        setDialogOllamaModelId(current);
        if (modelDialog != null) {
            modelDialog.pack();
        }
        if (reopen) {
            dialogOllamaId.setPopupVisible(false);
            dialogOllamaId.setPopupVisible(true);
        }
        dialogAdjusting = false;
    }

    /**
     * @param wireId id on the frame
     * @param openId id of the open modal
     * @return whether both name that modal
     */
    static boolean sameDialogCell(String wireId, String openId) {
        if (wireId == null || openId == null) {
            return false;
        }
        return wireId.equalsIgnoreCase(openId);
    }

    /**
     * Host tag names, then the typed id when that id is not already a row.
     *
     * @param text    stripped {@code tags_result:} body
     * @param current id in the field. Empty adds no row.
     * @return rows for the pull-down
     */
    static ArrayList<String> ollamaHostRows(String text, String current) {
        ArrayList<String> names = tagsResultModels(text);
        String typed = current == null ? "" : current.trim();
        if (typed.length() == 0) {
            return names;
        }
        for (int i = 0; i < names.size(); i++) {
            if (typed.equals(names.get(i))) {
                return names;
            }
        }
        names.add(typed);
        return names;
    }

    /**
     * @param text stripped {@code tags_result:} body
     * @return model tag names, in reply order
     */
    static ArrayList<String> tagsResultModels(String text) {
        ArrayList<String> names = new ArrayList<String>();
        if (text == null) {
            return names;
        }
        int start = 0;
        while (start <= text.length()) {
            int nl = text.indexOf('\n', start);
            String line = nl < 0 ? text.substring(start) : text.substring(start, nl);
            if (line.endsWith("\r")) {
                line = line.substring(0, line.length() - 1);
            }
            if (line.startsWith("model:")) {
                String name = line.substring("model:".length()).trim();
                boolean seen = false;
                for (int i = 0; i < names.size(); i++) {
                    if (names.get(i).equals(name)) {
                        seen = true;
                    }
                }
                if (name.length() > 0 && !seen) {
                    names.add(name);
                }
            }
            if (nl < 0) {
                break;
            }
            start = nl + 1;
        }
        return names;
    }

