    /**
     * Fill the Grok model combo from {@code grok_models_result:} while this modal is open on that cell.
     * A reply with no model lines leaves the static rows.
     *
     * @param cellId cell on the frame
     * @param text   stripped body
     */
    private void applyGrokModelsResult(String cellId, String text) {
        if (!grokDialogOpen || !sameDialogCell(cellId, dialogCellId) || dialogGrokModel == null) {
            return;
        }
        String current = dialogGrokModel.getSelectedItem() == null
                ? "" : String.valueOf(dialogGrokModel.getSelectedItem());
        ArrayList<String> rows = grokHostRows(text, current);
        if (rows.isEmpty()) {
            return;
        }
        boolean reopen = dialogGrokModel.isPopupVisible();
        dialogAdjusting = true;
        dialogGrokModel.removeAllItems();
        for (int i = 0; i < rows.size(); i++) {
            dialogGrokModel.addItem(rows.get(i));
        }
        int count = dialogGrokModel.getItemCount();
        dialogGrokModel.setMaximumRowCount(count > 0 ? count : 1);
        String chosen = current == null ? "" : current.trim();
        if (chosen.length() > 0) {
            dialogGrokModel.setSelectedItem(chosen);
        } else {
            dialogGrokModel.setSelectedIndex(-1);
        }
        if (modelDialog != null) {
            modelDialog.pack();
        }
        if (reopen) {
            dialogGrokModel.setPopupVisible(false);
            dialogGrokModel.setPopupVisible(true);
        }
        dialogAdjusting = false;
    }

    // @aa-sdd PK-8253 docs/specs/java/org/casserole/llm/llm.spec.md
    /**
     * Language-model ids, with an unknown current id first.
     * An empty parse returns an empty list, so the caller leaves the static rows.
     *
     * @param text    stripped {@code grok_models_result:} body
     * @param current id in the combo. Empty adds no extra row.
     * @return rows for the pull-down, or an empty list when the reply has no model lines
     */
    static ArrayList<String> grokHostRows(String text, String current) {
        ArrayList<String> names = tagsResultModels(text);
        if (names.isEmpty()) {
            return names;
        }
        String chosen = current == null ? "" : current.trim();
        if (chosen.length() == 0) {
            return names;
        }
        for (int i = 0; i < names.size(); i++) {
            if (chosen.equals(names.get(i))) {
                return names;
            }
        }
        names.add(0, chosen);
        return names;
    }

