    /**
     * @param text stripped {@code show_result:} body
     * @return model id on the first line, or empty
     */
    private static String showResultModel(String text) {
        if (text == null) {
            return "";
        }
        int nl = text.indexOf('\n');
        String first = nl < 0 ? text : text.substring(0, nl);
        if (!first.startsWith("show_result:")) {
            return "";
        }
        return first.substring("show_result:".length()).trim();
    }

    /**
     * @param text stripped {@code show_result:} body
     * @return {@code low}, {@code medium}, and {@code high} lines, in order
     */
    private static ArrayList<String> showResultValues(String text) {
        ArrayList<String> values = new ArrayList<String>();
        if (text == null) {
            return values;
        }
        int start = 0;
        while (start <= text.length()) {
            int nl = text.indexOf('\n', start);
            String line = nl < 0 ? text.substring(start) : text.substring(start, nl);
            if (line.startsWith("value:")) {
                String level = line.substring("value:".length()).trim();
                if (level.length() > 0 && !"true".equals(level) && !"false".equals(level)) {
                    values.add(level);
                }
            }
            if (nl < 0) {
                break;
            }
            start = nl + 1;
        }
        return values;
    }

    /**
     * The method label builds a themed label for one string.
     * The label text is {@code text}.
     * {@link SshClientTheme#applyLabel} paints the label.
     *
     * @param text The text is the words on the label.
     * @return The return value is the themed label.
     */
    private JLabel label(String text) {
        JLabel one = new JLabel(text);
        theme.applyLabel(one);
        return one;
    }

    /**
     * The method fillModels fills a model combo from the known Grok models.
     * Every current item is removed.
     * A null selection is treated as empty, and any other selection is trimmed.
     * If the trimmed selection is non-empty and is not one of {@link GrokSettingsDocument#MODELS}, that selection is added first.
     * Each known model is then added.
     * The maximum row count becomes the item count.
     * If the trimmed selection is non-empty, that item is selected.
     * If the trimmed selection is empty, the selected index becomes -1.
     *
     * @param model The model combo is the combo being filled.
     * @param selected The selected value is the model to select, and it may be null.
     */
    private static void fillModels(JComboBox<String> model, String selected) {
        model.removeAllItems();
        String chosen = selected == null ? "" : selected.trim();
        boolean known = false;
        for (int i = 0; i < GrokSettingsDocument.MODELS.length; i++) {
            if (GrokSettingsDocument.MODELS[i].equals(chosen)) {
                known = true;
            }
        }
        if (chosen.length() > 0 && !known) {
            model.addItem(chosen);
        }
        for (int i = 0; i < GrokSettingsDocument.MODELS.length; i++) {
            model.addItem(GrokSettingsDocument.MODELS[i]);
        }
        model.setMaximumRowCount(model.getItemCount());
        if (chosen.length() > 0) {
            model.setSelectedItem(chosen);
        } else {
            model.setSelectedIndex(-1);
        }
    }

    /**
     * The method fillEffort fills an effort combo for one Grok model.
     * {@link GrokSettingsDocument#effortRows} supplies the rows for {@code model}.
     * Every current item is removed, and then each row is added.
     * A null keep value is treated as empty.
     * If one row equals the keep value, that value is selected.
     * If no row equals the keep value, {@link GrokSettingsDocument#effortStart} supplies the selection.
     *
     * @param effort The effort combo is the combo being filled.
     * @param model The model is the Grok model id whose effort rows are shown.
     * @param keep The keep value is the effort to preserve, and it may be null.
     */
    private static void fillEffort(JComboBox<String> effort, String model, String keep) {
        String[] rows = GrokSettingsDocument.effortRows(model);
        effort.removeAllItems();
        for (int i = 0; i < rows.length; i++) {
            effort.addItem(rows[i]);
        }
        String chosen = keep == null ? "" : keep;
        boolean found = false;
        for (int i = 0; i < rows.length; i++) {
            if (rows[i].equals(chosen)) {
                found = true;
            }
        }
        effort.setSelectedItem(found ? chosen : GrokSettingsDocument.effortStart(model));
    }

    /**
     * The method numberText prints a double without a trailing fraction when the value is a whole number.
     * If the value equals its nearest integer and is not infinite, the method returns that value cast to a long.
     * Any other value is returned from {@code Double.toString}.
     *
     * @param value The value is the number to print.
     * @return The return value is the printed number.
     */
    private static String numberText(double value) {
        if (value == Math.rint(value) && !Double.isInfinite(value)) {
            return Long.toString((long) value);
        }
        return Double.toString(value);
    }

